using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BEOSurvey {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_ExperimentOperations/";static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");if(File.Exists(H+"scene_before.json"))throw new Exception("Baseline already exists");EditorSceneManager.SaveScene(s,H+"B4_before.unity",true);if(s.isDirty)throw new Exception("Unsaved user scene backed up; inspect before continuing");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;
 var objects=root.GetComponentsInChildren<Transform>(true).Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,path=P(t),position=V(t.position),rotation=V(t.eulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray();File.WriteAllText(H+"scene_before.json",JsonConvert.SerializeObject(objects,Formatting.Indented));
 var assets=root.GetComponentsInChildren<Transform>(true).Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).Select(t=>{var rr=t.GetComponentsInChildren<Renderer>();var bounds=new Bounds(t.position,Vector3.zero);if(rr.Length>0){bounds=rr[0].bounds;foreach(var r in rr.Skip(1))bounds.Encapsulate(r.bounds);}return new{name=t.name,path=P(t),asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),position=V(t.position),rotation=V(t.eulerAngles),active=t.gameObject.activeInHierarchy,boundsCenter=V(bounds.center),boundsSize=V(bounds.size)};}).ToArray();File.WriteAllText(H+"existing_assets.json",JsonConvert.SerializeObject(assets,Formatting.Indented));
 return new{scene=s.path,s.isDirty,transforms=objects.Length,instances=assets.Length,lights=root.GetComponentsInChildren<Light>().Length};}
}
